/** Editorially authored transfer tasks, never generated by rewording a runtime question.
 * A concept is deliberately narrower than a whole subject. Source links and teaching
 * sections are inherited from the existing reviewed lessons; scenarios are hypothetical. */
type Scenario = [prompt: string, correct: string, distractors: [string, string, string], explanation: string];
export type ConceptDefinition = { id: string; title: string; lessonIds: string[]; sourceQuestionIds: string[]; categoryId: string; subcategoryId: string; teachingSections: number[]; variants: ChoiceQuestion[] };
const teachingSections: Record<string, number[]> = { "arch-program": [0, 1, 1, 3], "arch-drawings": [1, 1, 0, 1], "arch-light": [1, 1, 1, 1], "arch-load-path": [0, 1, 2, 4], "arch-envelope": [1, 3, 0, 1], "arch-climate": [1, 3, 2, 4], "arch-access": [2, 0, 3, 1], "arch-reuse": [0, 2, 3, 4], "moon-geometry": [0, 0, 0, 2], "orbital-fall": [1, 0, 0, 0], "stellar-light": [1, 2, 2, 1], "planet-types": [0, 0, 1, 2], "transit-evidence": [0, 3, 2, 5], "sky-scattering": [1, 0, 0, 2], "athens-participation": [1, 1, 3, 3], "exchange-networks": [0, 3, 1, 3], "historical-evidence": [1, 1, 1, 0], "coral-symbiosis": [0, 1, 2, 0], "vent-energy": [1, 1, 0, 2], "dns-resolution": [1, 2, 1, 0], "key-roles": [0, 1, 1, 2], "plate-boundaries": [1, 3, 0, 3], "flood-space": [1, 1, 2, 2], "editing-context": [1, 1, 3, 2] };
function concept(id: string, title: string, lessonIds: string[], scenarios: Scenario[], sourceQuestionIds: string[] = [], difficulty: QuestionDifficulty = "medium"): ConceptDefinition {
  const lesson = lessons.find(l => l.id === lessonIds[0]);
  if (!lesson || lessonIds.some(id => !lessons.some(l => l.id === id))) throw new Error("invalid_concept_lesson");
  return { id, title, lessonIds, sourceQuestionIds, categoryId: lesson.categoryId, subcategoryId: lesson.subcategoryId, teachingSections: teachingSections[id],
    variants: scenarios.map(([prompt, correct, distractors, explanation], index) => {
      const choices = [correct, ...distractors], shift = index % 4, answers = [...choices.slice(shift), ...choices.slice(0, shift)];
      const content = { answers, correctIndex: answers.indexOf(correct) };
      return { id: `transfer:${id}:v${index + 1}`, type: "multiple-choice", version: contentVersion(prompt, content, "transfer-1"), categoryId: lesson.categoryId, subcategoryId: lesson.subcategoryId, conceptIds: [id], difficulty, difficultyOrigin: "editorial", prompt, explanation, sources: lesson.sources.map(s => ({ ...s })), content };
    }) };
}
